<?= $this->extend('layouts/app') ?><?= $this->section('content') ?><?= view('partials/breadcrumbs',['title'=>'Reports','subtitle'=>'Filter, print, and export operational equipment reports.']) ?><section class="panel"><div class="panel-head report-head"><form method="get" class="toolbar"><select name="type"><?php foreach(['inventory'=>'Equipment Inventory','available'=>'Available Equipment','borrowed'=>'Borrowed Equipment','overdue'=>'Overdue Equipment','damaged'=>'Damaged Equipment','maintenance'=>'Maintenance','history'=>'Borrowing History'] as $k=>$v): ?><option value="<?= $k ?>" <?= $type===$k?'selected':'' ?>><?= esc($v) ?></option><?php endforeach; ?></select><select name="category_id"><option value="">All categories</option><?php foreach($categories as $c): ?><option value="<?= $c['id'] ?>" <?= (int)$filters['category_id']===(int)$c['id']?'selected':'' ?>><?= esc($c['name']) ?></option><?php endforeach; ?></select><select name="equipment_id"><option value="">All equipment</option><?php foreach($equipment as $e): ?><option value="<?= $e['id'] ?>" <?= (int)$filters['equipment_id']===(int)$e['id']?'selected':'' ?>><?= esc($e['asset_code'].' · '.$e['name']) ?></option><?php endforeach; ?></select><select name="borrower_id"><option value="">All borrowers</option><?php foreach($borrowers as $b): ?><option value="<?= $b['id'] ?>" <?= (int)$filters['borrower_id']===(int)$b['id']?'selected':'' ?>><?= esc($b['display_name']) ?></option><?php endforeach; ?></select><select name="status"><option value="">All statuses</option><optgroup label="Equipment"><?php foreach(config('BantayGamit')->equipmentStatuses as $k=>$v): ?><option value="<?= esc($k) ?>" <?= $filters['status']===$k?'selected':'' ?>><?= esc($v) ?></option><?php endforeach; ?></optgroup><optgroup label="Borrow Requests"><?php foreach(config('BantayGamit')->requestStatuses as $k=>$v): ?><option value="<?= esc($k) ?>" <?= $filters['status']===$k?'selected':'' ?>><?= esc($v) ?></option><?php endforeach; ?></optgroup><optgroup label="Maintenance"><?php foreach(config('BantayGamit')->maintenanceStatuses as $k=>$v): ?><option value="<?= esc($k) ?>" <?= $filters['status']===$k?'selected':'' ?>><?= esc($v) ?></option><?php endforeach; ?></optgroup></select><input type="date" name="from" value="<?= esc($filters['from']) ?>"><input type="date" name="to" value="<?= esc($filters['to']) ?>"><button class="btn" type="submit">Apply</button></form><div class="actions"><a class="btn" target="_blank" href="<?= site_url('reports/print').'?'.http_build_query(['type'=>$type]+$filters) ?>"><?= ui_icon('printer') ?> Print</a><a class="btn primary" href="<?= site_url('reports/xlsx').'?'.http_build_query(['type'=>$type]+$filters) ?>"><?= ui_icon('save') ?> Excel Export</a></div></div><div class="table-wrap"><table><?php if($rows): ?><thead><tr><?php foreach(array_keys($rows[0]) as $col): ?><th><?= esc(status_label($col)) ?></th><?php endforeach; ?></tr></thead><tbody><?php foreach($rows as $row): ?><tr><?php foreach($row as $value): ?><td><?= esc((string)($value??'—')) ?></td><?php endforeach; ?></tr><?php endforeach; ?></tbody><?php else: ?><tbody><tr><td><div class="empty">No report data matches the selected filters.</div></td></tr></tbody><?php endif; ?></table></div></section><?= $this->endSection() ?>
